285	test('squash-merge-history: flags a merge the work introduces, silent on linear history and pre-existing main merges', () => {
286	  const linear = makeRepo({ changed: { 'f.txt': 'x\n' } });
287	
288	  // A merge commit on the feature branch itself — the current change introduces it → fires.
289	  const introduced = makeRepo({ changed: { 'f.txt': 'x\n' } });
290	  git(introduced, 'checkout', '-q', '-b', 'side');
291	  writeFiles(introduced, { 's.txt': 'x\n' });
292	  git(introduced, 'add', '-A');
293	  git(introduced, 'commit', '-q', '-m', 'side work');
294	  git(introduced, 'checkout', '-q', 'feature');
295	  git(introduced, 'merge', '-q', '--no-ff', '-m', 'merge side into feature', 'side');
296	
297	  // A merge commit already on main, before the branch's work — the repo's history, not the work → silent.
298	  const preexisting = makeRepo({ changed: {} });
299	  git(preexisting, 'checkout', '-q', 'main');
300	  git(preexisting, 'checkout', '-q', '-b', 'side');
301	  writeFiles(preexisting, { 's.txt': 'x\n' });
302	  git(preexisting, 'add', '-A');
303	  git(preexisting, 'commit', '-q', '-m', 'side work');
304	  git(preexisting, 'checkout', '-q', 'main');
305	  git(preexisting, 'merge', '-q', '--no-ff', '-m', 'merge side', 'side');
306	  git(preexisting, 'checkout', '-q', '-B', 'feature', 'main'); // branch fresh off post-merge main
307	  writeFiles(preexisting, { 'w.txt': 'x\n' });
308	  git(preexisting, 'add', '-A');
309	  git(preexisting, 'commit', '-q', '-m', 'feature work');
310	
311	  try {
312	    const findings = run(squashMergeHistory, introduced);
313	    assert.equal(findings.length, 1);
314	    assert.match(findings[0].what, /merge side into feature/);
315	    assert.match(findings[0].file, /^feature@/);
316	    assert.equal(run(squashMergeHistory, linear).length, 0);
317	    assert.equal(run(squashMergeHistory, preexisting).length, 0);
318	  } finally { cleanup(linear); cleanup(introduced); cleanup(preexisting); }
319	});
